      buffer.put(bytes.length, lenBits);
      for (var i = 0; i < bytes.length; i++) buffer.put(bytes[i], 8);

      var rsBlocks = getRsBlocks(this.typeNumber, this.ecIdx);
      var totalDataCount = 0;
      for (var i = 0; i < rsBlocks.length; i++) totalDataCount += rsBlocks[i].data;

